#!/usr/bin/env bash
# Documentation : « Légal et RGPD » en quatre chapitres ; plages recalées.
# Prérequis : apply-fix-legal.sh et apply-docs-membres.sh. Aucune migration.
# Usage (racine du repo) : bash apply-docs-legal.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/legal/consentement-en-ligne.mdx" 2>/dev/null | grep -qF "Le consentement en ligne"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "assertPasswordOfConnectedUser" "packages/backend/src/modules/auth/router.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-legal.sh"; exit 1; }
grep -qF "Une hiérarchie qui transmet ses droits vers le bas" "apps/web/content/docs/dev/membres/les-groupes.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-membres.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/api/fabriquer-une-procedure.mdx" "apps/web/content/docs/dev/api/gerer-les-erreurs.mdx" "apps/web/content/docs/dev/api/le-routeur-metier.mdx" "apps/web/content/docs/dev/auth/fermer-une-session.mdx" "apps/web/content/docs/dev/auth/le-mot-de-passe-oublie.mdx" "apps/web/content/docs/dev/auth/lire-la-session.mdx" "apps/web/content/docs/dev/legal/documents-legaux-et-donnees.mdx" "apps/web/content/docs/dev/legal/droit-a-l-image.mdx")
EXPECT=("5aac4997b86d:apps/web/content/docs/dev/api/fabriquer-une-procedure.mdx" "ead73bb9bf46:apps/web/content/docs/dev/api/gerer-les-erreurs.mdx" "3f8ef73c8c96:apps/web/content/docs/dev/api/le-routeur-metier.mdx" "efd11fb601d5:apps/web/content/docs/dev/auth/fermer-une-session.mdx" "d305fe968c93:apps/web/content/docs/dev/auth/le-mot-de-passe-oublie.mdx" "4b8f394f2e65:apps/web/content/docs/dev/auth/lire-la-session.mdx" "3f65db816108:apps/web/content/docs/dev/legal/documents-legaux-et-donnees.mdx" "60a11ebb60b3:apps/web/content/docs/dev/legal/droit-a-l-image.mdx")
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=("apps/web/content/docs/dev/legal/consentement-en-ligne.mdx" "apps/web/content/docs/dev/legal/donnees-personnelles.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Le consentement en ligne" "apps/web/content/docs/dev/legal/consentement-en-ligne.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/legal"
