MODIFIED+=("$F")
python3 - "$F" <<'PY2'
import re, sys
p = sys.argv[1]; s = open(p, encoding="utf-8").read()
new = "[\"Légal et RGPD\",\"En quatre chapitres : les pages légales (générées depuis les réglages, un registre décrit une seule fois) ; les données personnelles (durées tenues chaque nuit, comptes jamais supprimés sans décision, export) ; le droit à l’image (un formulaire signé hors de la bibliothèque, un statut qui en découle, une preuve gardée cinq ans) ; le consentement en ligne (le mot de passe qui vaut signature, un récapitulatif figé et versionné).\",\"rédigée\"]"
s2, n = re.subn(r'\["Légal et RGPD","[^"]*","[^"]*"\]', lambda m: new, s)
assert n == 1, n
open(p, "w", encoding="utf-8").write(s2)
PY2
[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm --filter backend typecheck && pnpm typecheck && pnpm lint"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
git add -- "${MODIFIED[@]}" "${CREATED[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
docs(legal): quatre chapitres

- Les pages légales : getLegalInfo pas à pas, Val, les coordonnées légales, saveLegal, le registre
  des traitements décrit une seule fois (et complété : parent référent, majorité, dernière connexion)
- Les données personnelles (nouveau) : purgeExpiredData pas à pas, la minuterie de 3 h, les comptes
  inactifs signalés, l'export et ce qu'il ne contient pas
- Le droit à l'image : les usages, le rangement hors application, registerImageConsentForm pas à
  pas, le statut déduit, la route, le détachement et la purge (le fichier d'abord)
- Le consentement en ligne (nouveau) : la majorité effective, onlineConsentState,
  confirmMemberConsent pas à pas, les essais de mot de passe limités, la version du texte, les mineurs
- Index ; plages de lignes recalées (authentification, API) ; changePassword et ses essais limités

